#!/usr/bin/env python3
"""make_story.py — writes the story, characters, 20 districts and their missions, protest debates,
posters and patients for Taunt-o-Nomics: Dhaka into data/story/*.json.
All people, colleges, hospitals and the Syndicate are fictional. Real place names are used only as
settings. Lethal missions target the fictional Syndicate only; students and protesters are won over
in debates and are never combat targets."""
import json, os, sys

OUT = sys.argv[1] if len(sys.argv) > 1 else os.path.join(os.path.dirname(__file__), "..", "data", "story")
os.makedirs(OUT, exist_ok=True)

def w(name, obj):
    with open(os.path.join(OUT, name), "w", encoding="utf-8") as f:
        json.dump(obj, f, ensure_ascii=False, indent=1)
    print("wrote", name)

