# ------------------------------------------------------------------ helpers for missions
def M(mid, title, brief, steps, reward=None, time=None):
    return {"id": mid, "title": title, "brief": brief, "steps": steps, "reward": reward or {"money": 400}, "time": time}
def goto(poi, text, r=6.0): return {"type": "goto", "poi": poi, "text": text, "radius": r}
def talk(npc, poi, text, lines): return {"type": "talk", "npc": npc, "poi": poi, "text": text, "lines": lines}
def exam(npc, poi, text, count, need, cats): return {"type": "exam", "npc": npc, "poi": poi, "text": text, "count": count, "pass": need, "cats": cats}
def collect(item, n, poi, text): return {"type": "collect", "item": item, "count": n, "poi": poi, "text": text}
def posters(n, text, kind="bcs_quiz"): return {"type": "posters", "count": n, "kind": kind, "text": text}
def defeat(n, poi, text, kind="goon"): return {"type": "defeat", "count": n, "enemy": kind, "poi": poi, "text": text}
def survive(sec, poi, text, waves=3): return {"type": "survive", "seconds": sec, "poi": poi, "waves": waves, "text": text}
def eliminate(target, poi, text, guards=3): return {"type": "eliminate", "target": target, "poi": poi, "guards": guards, "text": text}
def roof(poi, text, chasers=4): return {"type": "escape_roof", "poi": poi, "chasers": chasers, "text": text}
def debate(did, poi, text): return {"type": "debate", "debate": did, "poi": poi, "text": text}
def tail(npc, a, b, text): return {"type": "tail", "npc": npc, "from": a, "to": b, "text": text}
def sneak(poi, text, guards=4): return {"type": "sneak", "poi": poi, "guards": guards, "text": text}
def deliver(item, npc, poi, text): return {"type": "deliver", "item": item, "npc": npc, "poi": poi, "text": text}
def night(text, banish=1): return {"type": "survive_night", "banish": banish, "text": text}
def advise(pids, poi, text): return {"type": "advise", "patients": pids, "poi": poi, "text": text}
def swap(n, poi, text): return {"type": "swap", "count": n, "poi": poi, "text": text}
def drive(poi, text): return {"type": "drive", "poi": poi, "text": text}
def scene(lines, text="..."): return {"type": "cutscene", "lines": lines, "text": text}
def boss(text): return {"type": "boss", "text": text}
def buy(item, npc, poi, text, price): return {"type": "buy", "item": item, "npc": npc, "poi": poi, "price": price, "text": text}

S = "sakib"
def L(i, act, name, sub, style, tod, intro, missions, size=14, river=False):
    return {"id": i, "act": act, "name": name, "subtitle": sub, "style": style, "time": tod, "intro": intro,
            "missions": missions, "size": size, "river": river, "seed": 1000 + i * 37}

